(() => {
'use strict';
const state=window.observatory={active:false,yaw:0,pitch:0,zoom:55};
const panel=document.querySelector('#scope-explorer'),surface=document.querySelector('#scope-drag'),launch=document.querySelector('#scope-launch'),exit=document.querySelector('#scope-exit'),reset=document.querySelector('#scope-reset'),zoom=document.querySelector('#scope-zoom');let drag=null,returnFocus;
const back=document.querySelector('#scope-return'),contact=document.querySelector('#cosmic-contact');
let changing=false;const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms)),gentle=()=>document.body.classList.contains('reduced');
function resetView(){state.yaw=0;state.pitch=0;state.zoom=55;zoom.value='55'}
async function close(){if(changing||!state.active)return false;changing=true;document.body.classList.add('scope-leaving');panel.classList.add('scope-out');if(!gentle())await pause(220);state.active=false;drag=null;panel.hidden=true;panel.classList.remove('scope-out');document.body.classList.remove('is-exploring','is-dragging');if(returnFocus)returnFocus.focus({preventScroll:true});requestAnimationFrame(()=>requestAnimationFrame(()=>document.body.classList.remove('scope-leaving')));changing=false;return true}
async function open(reset=false){if(changing||state.active)return;changing=true;returnFocus=reset?launch:back;if(contact.open)contact.close();if(reset)resetView();document.body.classList.add('scope-entering');if(!gentle())await pause(240);state.active=true;panel.hidden=false;document.body.classList.add('is-exploring');document.body.classList.remove('scope-entering');surface.focus({preventScroll:true});changing=false}
launch.onclick=()=>open(true);back.onclick=()=>open();document.querySelector('#contact-back-to-scope').onclick=()=>open();exit.onclick=close;reset.onclick=resetView;zoom.oninput=()=>state.zoom=Number(zoom.value);
document.addEventListener('click',event=>{if(event.target.closest('.star-link,[data-sky-link],#sky-contact'))back.hidden=false},true);
surface.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('a,button,input'))return;drag={id:event.pointerId,x:event.clientX,y:event.clientY,yaw:state.yaw,pitch:state.pitch};surface.setPointerCapture(event.pointerId);document.body.classList.add('is-dragging')});
surface.addEventListener('pointermove',event=>{if(!drag||drag.id!==event.pointerId)return;const scale=state.zoom/55;state.yaw=Math.max(-1.5,Math.min(1.5,drag.yaw-(event.clientX-drag.x)*.0035*scale));state.pitch=Math.max(-.75,Math.min(.75,drag.pitch-(event.clientY-drag.y)*.003*scale))});
function release(){drag=null;document.body.classList.remove('is-dragging')}surface.addEventListener('pointerup',release);surface.addEventListener('pointercancel',release);surface.addEventListener('lostpointercapture',release);
document.addEventListener('keydown',event=>{if(!state.active||document.querySelector('#cosmic-contact').open)return;if(event.key==='Escape'){close();event.preventDefault()}if(event.target.matches('input'))return;const moves={ArrowLeft:[.075,0],ArrowRight:[-.075,0],ArrowUp:[0,.06],ArrowDown:[0,-.06]};if(moves[event.key]){event.preventDefault();state.yaw=Math.max(-1.5,Math.min(1.5,state.yaw+moves[event.key][0]));state.pitch=Math.max(-.75,Math.min(.75,state.pitch+moves[event.key][1]))}if(event.key.toLowerCase()==='r')resetView();if(event.key==='Tab'){const focusable=[...panel.querySelectorAll('button:not([hidden]),a:not([hidden]),input,[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
panel.querySelectorAll('[data-sky-link]').forEach(link=>link.addEventListener('click',async event=>{event.preventDefault();event.stopImmediatePropagation();const href=link.getAttribute('href');if(await close())requestAnimationFrame(()=>document.querySelector('.quick-nav a[href="'+href+'"]').click())}));
document.querySelector('#sky-contact').onclick=async()=>{if(await close())document.querySelector('#contact-object').click()};
})();
